-- Resources content for Sourcework's project synthesis (CLAUDE.md, "Resources stay in step with the code").
-- Content only; no schema.

select private.rc_release_guide(
  p_slug => 'sourcework-synthesis',
  p_tool_key => 'transcription',
  p_title => 'Synthesis',
  p_summary => 'Read what a project''s accepted findings establish for each research question, where accounts conflict and what is still open.',
  p_screen_keys => array['sourcework.synthesis'],
  p_sort_order => 20,
  p_version_note => 'First version',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Synthesis reads every finding you have accepted in a project and says what they establish about each of your research questions: what is established, what is contested, what is uncertain, where accounts conflict and what the sources leave open. It is a reading aid. Every statement opens onto the findings behind it, and nothing in it is evidence on its own."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Write a synthesis"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open a project and select "},{"type":"text","text":"Synthesis","marks":[{"type":"bold"}]},{"type":"text","text":". The tab appears once the project has an accepted finding."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Synthesize","marks":[{"type":"bold"}]},{"type":"text","text":". One run reads all the accepted findings together. It can take a few minutes, because the model may search the transcripts to check a finding that looks thin or two that seem to conflict. You can leave the tab open and come back."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A project with no research question gets one section for all its findings. Questions on the Setup tab give each one its own section."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How to read it"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Established","marks":[{"type":"bold"}]},{"type":"text","text":" means independent sources, or a firsthand account and a record, agree. "},{"type":"text","text":"Contested","marks":[{"type":"bold"}]},{"type":"text","text":" means credible findings conflict. "},{"type":"text","text":"Uncertain","marks":[{"type":"bold"}]},{"type":"text","text":" means the support is thin, secondhand or unconfirmed. Several findings from one source count as one source’s account, and the line under each statement says how many findings, sources and speakers stand behind it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the line under a statement to read the findings behind it and listen to where each was said."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where accounts conflict","marks":[{"type":"bold"}]},{"type":"text","text":" lists real disagreements: an official account against a firsthand one, a memory against a record, a figure that changed. Each side shows its position and its findings."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Still open","marks":[{"type":"bold"}]},{"type":"text","text":" names what a reporter could go and get before relying on a statement."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Worth hearing","marks":[{"type":"bold"}]},{"type":"text","text":" points at moments in the recordings that a paraphrase would lose. They are not findings; open one to listen."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Keeping it current"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When findings change after a version was written, the tab says how many. "},{"type":"text","text":"Update synthesis","marks":[{"type":"bold"}]},{"type":"text","text":" writes a new version from the current findings."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Every run writes a new version and keeps the earlier ones. Open an earlier version under Earlier versions to read it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A statement whose findings you have since rejected is marked as having no accepted finding behind it, so you can see what no longer holds."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Synthesis uses only accepted findings, never suggestions you have not reviewed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The text of every statement is the model’s wording. To use a speaker’s own words, make an excerpt."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Themes from before this change stay readable. A project with themes still shows the Themes tab; a project without them does not."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-themes',
  p_tool_key => 'transcription',
  p_title => 'Themes',
  p_summary => 'See what several sources say in common, decide on suggested themes, and read the evidence for and against each one.',
  p_screen_keys => array['sourcework.themes', 'sourcework.theme'],
  p_sort_order => 21,
  p_version_note => 'Synthesis replaces themes for new projects',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A theme is a statement that your project’s sources bear out or push against, such as “Locals treated the fort’s tunnels as a private playground”. A topic such as “Childhood” is not a theme. Themes show how broadly something is backed, and they keep the evidence against it beside the evidence for it. Everything the model proposes waits for your decision."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Open the Themes tab"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a project and select "},{"type":"text","text":"Themes","marks":[{"type":"bold"}]},{"type":"text","text":". The tab now appears only on projects that already have themes, because Synthesis has replaced themes as the way to an answer. Its badge counts the suggestions waiting for you. "},{"type":"text","text":"Waiting for you","marks":[{"type":"bold"}]},{"type":"text","text":" lists data points still to review in each source, accepted data points that are not in a theme yet, and suggestions to decide on."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review themes"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Review themes","marks":[{"type":"bold"}]},{"type":"text","text":". It first files accepted data points into the themes you have already accepted, then reads the ones left over and proposes new themes and merges between accepted themes. It takes a minute or two, and you can leave the page open in another tab."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accept keeps a suggestion. Reject hides it, and it is not proposed again. Put back for review is under the Rejected filter."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Edit opens the theme to reword it. Saving a suggestion accepts it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A suggestion marked Reads like a topic is a subject heading rather than a claim. Edit it into a sentence that says something."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A theme marked Single source is backed by one source only. That is a flag, not a verdict."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A merge suggestion says two themes are the same claim in different words. Accepting moves the data points across and records why in the memo of the theme that stays."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Accepted themes are never reworded by a later run."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How a data point gets into a theme"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Automatically: when you accept a data point, the model checks it against your accepted themes and files it where it fits, as supporting or complicating. One that fits none waits until you accept a new theme or choose Review themes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"By hand: on a theme’s page, Add data points lists accepted data points that are not in it. The ⋮ beside a piece of evidence changes it between supporting and complicating, or removes it. A removed data point is not put back by a later run."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To make a theme yourself, choose + New theme on the Themes tab."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The theme page"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a theme to read its evidence by source, with supporting and complicating data points side by side. Select the play button to open the source at that passage. Breadth shows how many of the project’s sources and speakers back the theme. The memo is yours: Review themes never reads or changes it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only accepted data points count toward a theme. Un-accepting one removes it from the numbers without deleting it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Filing and reviewing send your data points’ wording to an outside service, as extraction does."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything here works on a phone: the table becomes cards and the evidence stacks."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-23-sourcework-synthesis',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-23',
  p_title => 'Sourcework: Synthesis answers each research question',
  p_guide_slugs => array['sourcework-synthesis', 'sourcework-themes'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourcework has a new "},{"type":"text","text":"Synthesis","marks":[{"type":"bold"}]},{"type":"text","text":" tab. One run reads every accepted finding in a project and writes, for each research question, what is established, contested or uncertain, where accounts conflict, and what is still open. Each statement opens onto the findings and passages behind it, and every run keeps the earlier versions. Synthesis replaces themes as the way from findings to an answer: the Themes tab now shows only on projects that already have themes, and the Setup tab’s status ends with Synthesize instead of Review themes."}]}]}$body$
);
